input.command:
cd /work; { sed -n '/^DROP/,/^);$/p' schema.sql | sed -n '1,$p'; } > /dev/null
{ awk '/^DROP/,0' schema.sql | sed '/^-- =====/,$d'; cat <<'EOF'
-- Bulk load (set-based generate_series; deterministic pseudo-random data)
INSERT INTO customers (customer_id, customer_name, email, country)
SELECT g, 'Customer '||g, 'c'||g||'@example.com',
       (ARRAY['US','DE','FR','GB','JP','BR','IN','CA'])[1+(g%8)]
FROM generate_series(1,10000) g;

INSERT INTO products (product_id, product_name, category, unit_price)
SELECT g, 'Product '||g,
       (ARRAY['Books','Electronics','Toys','Garden','Clothing','Food','Sports','Beauty'])[1+(g%8)],
       round((5 + (hashint4(g)::bigint & 1023)/4.0)::numeric, 2)
FROM generate_series(1,1000) g;

INSERT INTO orders (order_id, customer_id, order_date, status, total_amount)
SELECT g,
       1 + (abs(hashint4(g)) % 10000),
       timestamptz '2025-06-01' + (abs(hashint4(g*7+1)) % (487*86400)) * interval '1 second',
       CASE WHEN abs(hashint4(g*3)) % 100 < 50 THEN 'COMPLETED'
            WHEN abs(hashint4(g*3)) % 100 < 75 THEN 'PENDING'
            WHEN abs(hashint4(g*3)) % 100 < 90 THEN 'CANCELLED'
            ELSE 'REFUNDED' END,
       0
FROM generate_series(1,100000) g;

INSERT INTO order_items (order_item_id, order_id, product_id, quantity, unit_price)
SELECT row_number() OVER (), o.order_id, p.product_id, 1 + abs(hashint4(o.order_id*5+n)) % 5, p.unit_price
FROM orders o
CROSS JOIN LATERAL generate_series(1, 1 + abs(hashint4(o.order_id*11)) % 5) n
JOIN products p ON p.product_id = 1 + abs(hashint4(o.order_id*13+n)) % 1000;

UPDATE orders o SET total_amount = s.t
FROM (SELECT order_id, sum(quantity*unit_price) t FROM order_items GROUP BY order_id) s
WHERE s.order_id = o.order_id;

-- Indexes for target_query.sql
CREATE INDEX orders_status_date_idx ON orders (status, order_date) INCLUDE (order_id);
CREATE INDEX order_items_order_id_idx ON order_items (order_id);
CREATE INDEX order_items_product_id_idx ON order_items (product_id);

VACUUM ANALYZE customers;
VACUUM ANALYZE products;
VACUUM ANALYZE orders;
VACUUM ANALYZE order_items;
EOF
} > solution.sql
psql -q -c 'drop schema public cascade; create schema public;' && psql -q -v ON_ERROR_STOP=1 -f solution.sql && psql -c 'select count(*) from orders' -c 'select count(*) from order_items' && (echo 'EXPLAIN ANALYZE'; sed '/^--/d' target_query.sql) | psql

